                                                                                                                                                                                                       
  CREATE TABLE "AUTH_ROLE"                                                                                                                                                                  
   (	"ROLE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 100 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"CREATION_DATE" DATE,                                                                                                                                                                                 
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"UPDATE_DATE" DATE,                                                                                                                                                                                   
	"REMARK" NVARCHAR2(512),                                                                                                                                                                              
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                          
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                   
	"NAME" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                                 
	"IS_DEFAULT" NUMBER,                                                                                                                                                                                  
	"APP_ID" NUMBER,                                                                                                                                                                                      
	"AUTH_LEVEL" NUMBER,                                                                                                                                                                                  
	"APP_CODE" NVARCHAR2(50),                                                                                                                                                                             
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                         
	 CONSTRAINT "AUTH_ROLE_PK" PRIMARY KEY ("ROLE_ID")                                                                                                                                                    
  USING INDEX  ENABLE                                                                                                                                                                                  
   ) ;                                                                                                                                                                                                 

